<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;

/**
 * Production-ready management question seeder.
 * Contains all 177 elite IIT/IIM/Oxford Saïd academic questions for all management disciplines:
 * BBA, MBA Core, MBA Marketing, MBA Finance, and MBA HR.
 *
 * Matching the exact scale and rigor of the engineering disciplines (ECE/EEE).
 */
class ManagementQuestionSeeder extends Seeder
{
    public function run(): void
    {
        $now = now();
        $subjects = [];
        $topics = [];

        foreach (DB::table('core_subjects')->get(['id', 'discipline_code', 'code']) as $s) {
            $subjects[$s->discipline_code][$s->code] = (int) $s->id;
        }

        foreach (DB::table('core_topics')->get(['id', 'subject_id', 'name']) as $t) {
            $topics[(int) $t->subject_id][mb_strtolower($t->name)] = (int) $t->id;
        }

        $questions = $this->questions();
        $inserted = 0;
        $updated = 0;

        foreach ($questions as $q) {
            $discipline = $q['discipline'];
            $subjectCode = $q['subject'];
            $subjectId = $subjects[$discipline][$subjectCode] ?? null;

            if ($subjectId === null) {
                $this->command?->warn("Subject {$subjectCode} for discipline {$discipline} not found. Skipping {$q['external_id']}.");
                continue;
            }

            $topicName = mb_strtolower($q['topic'] ?? '');
            $topicId = $topics[$subjectId][$topicName] ?? null;

            $numeric = ($q['type'] ?? 'mcq_single') === 'numeric';
            $options = $numeric ? null : array_map(
                fn (string $id) => ['id' => $id, 'text' => $q["option_{$id}"]],
                array_values(array_filter(['a', 'b', 'c', 'd', 'e', 'f'], fn (string $id) => isset($q["option_{$id}"]) && trim((string) $q["option_{$id}"]) !== ''))
            );

            $correct = $numeric ? null : (isset($q['correct']) ? [strtolower($q['correct'])] : null);

            $existing = DB::table('core_questions')->where('external_id', $q['external_id'])->first();

            $data = [
                'discipline_code' => $discipline,
                'subject_id' => $subjectId,
                'topic_id' => $topicId,
                'type' => $q['type'] ?? 'mcq_single',
                'stem' => $q['question'],
                'options' => $options === null ? null : json_encode($options, JSON_UNESCAPED_UNICODE),
                'correct' => $correct === null ? null : json_encode($correct),
                'numeric_min' => $numeric ? ($q['numeric_min'] ?? null) : null,
                'numeric_max' => $numeric ? ($q['numeric_max'] ?? null) : null,
                'numeric_unit' => $numeric ? ($q['numeric_unit'] ?? null) : null,
                'marks' => $q['marks'] ?? 1,
                'negative_marks' => $q['negative_marks'] ?? 0.25,
                'difficulty' => $q['difficulty'] ?? 'medium',
                'explanation' => $q['explanation'] ?? '',
                'tags' => json_encode(array_values(array_filter(array_map('trim', explode(';', (string) ($q['tags'] ?? '')))))),
                'source' => $q['source'] ?? 'IIT/IIM & Oxford Saïd Level Domain Question Bank',
                'usage' => $q['usage'] ?? 'both',
                'status' => 'published',
                'version' => 1,
                'published_at' => $existing?->published_at ?? $now,
                'updated_at' => $now,
            ];

            if ($existing) {
                DB::table('core_questions')->where('id', $existing->id)->update($data);
                $updated++;
            } else {
                $data['public_id'] = (string) Str::ulid();
                $data['external_id'] = $q['external_id'];
                $data['attempts_count'] = 0;
                $data['created_at'] = $now;
                DB::table('core_questions')->insert($data);
                $inserted++;
            }
        }

        $this->command?->info("ManagementQuestionSeeder finished: {$inserted} inserted, {$updated} updated (total: " . count($questions) . ").");
    }

