                'negative_marks' => 0.5,
                'question' => 'A monopoly firm faces a price elasticity of demand equal to $\\epsilon_p = -2.5$. The marginal cost of producing one additional unit is constant at $\\$60$. Using the Lerner Index of monopoly power and the optimal mark-up rule $P = \\frac{MC}{1 + 1/\\epsilon_p}$, what is the profit-maximizing price?',
                'explanation' => 'The Lerner rule for optimal monopoly pricing is $P = MC \\times \\frac{\\epsilon}{\\epsilon + 1}$ where $\\epsilon = |\\epsilon_p| = 2.5$. Thus, $P = 60 \\times \\frac{2.5}{2.5 - 1} = 60 \\times \\frac{2.5}{1.5} = 60 \\times \\frac{5}{3} = \\$100$. Check: Lerner Index $L = (P - MC)/P = (100 - 60)/100 = 0.40 = 1/2.5$.',
                'tags' => 'MBA;Economics;Lerner Index;Monopoly Pricing;IIT-Oxford Benchmark',
