                'explanation' => '$EOQ = \\sqrt{(2 \\times 10,000 \\times 50) / 4} = \\sqrt{1,000,000 / 4} = \\sqrt{250,000} = 500$ units. At EOQ, annual ordering cost = $(D/Q) \\times S = (10,000/500) \\times 50 = 20 \\times 50 = \\$1,000$. Annual holding cost = $(Q/2) \\times H = (500/2) \\times 4 = 250 \\times 4 = \\$1,000$. Total relevant inventory cost = $1,000 + $1,000 = \\$2,000$.',
