                'explanation' => 'Apply Bayes\' Theorem: $P(\\text{Fraud}|\\text{Alert}) = \\frac{P(\\text{Alert}|\\text{Fraud}) P(\\text{Fraud})}{P(\\text{Alert})}$. Prior $P(F) = 0.01$, $P(\\neg F) = 0.99$. Total Probability of Alert $P(A) = (0.95 \\times 0.01) + (0.05 \\times 0.99) = 0.0095 + 0.0495 = 0.0590$. Posterior $P(F|A) = \\frac{0.0095}{0.0590} \\approx 16.1\\%$. Despite a 95% test accuracy, base-rate fallacy causes the vast majority of alerts to be false positives.',
