                'question' => 'In a 1-step Binomial tree model, a stock currently at $S_0 = \\$100$ will either move up to $S_u = \\$120$ or down to $S_d = \\$80$ over one period. The risk-free rate is $r = 10\\%$ per period. A call option has strike $K = \\$100$. Under risk-neutral valuation, what is the risk-neutral probability of an upward move $p$ and the value of the call option?',
                'explanation' => 'Risk-neutral probability $p = \\frac{(1 + r) - d}{u - d}$. Here $u = 1.20$, $d = 0.80$, $1+r = 1.10$. $p = \\frac{1.10 - 0.80}{1.20 - 0.80} = \\frac{0.30}{0.40} = 0.75$. Option payoffs at expiration: $C_u = \\max(0, 120 - 100) = \\$20$; $C_d = \\max(0, 80 - 100) = \\$0$. Option value $C_0 = \\frac{p C_u + (1 - p) C_d}{1 + r} = \\frac{(0.75 \\times 20) + (0.25 \\times 0)}{1.10} = \\frac{15}{1.10} = \\$13.64$.',
